func pcRestore(cx *port.Cells) int32 {
	// Q: pops only what this stream pushed.
	var d int32 = port.CellsAt(cx, cDepth)
	var base int32 = port.CellsAt(cx, cGsbase)
	if d <= base {
		pcWarnSet(cx, wStates)
		return 0
	}
	pcCopyCells(cx, cCur, cStack+((d-1)*gsStride), gsStride)
	port.CellsSet(cx, cDepth, d-1)
	return 1
}

func pcUpdateM(cx *port.Cells) int32 {
	// M = Tm x CTM, the matrix from text space to page space.
	fx.MxMul(cx, cM, cTm, cCur+gCtm)
	return 0
}

func pcAdvance(cx *port.Cells, dx int64, dy int64) int32 {
	// Move the text position by (dx, dy) in TEXT space: Tm and M both translate
	// by the vector through their own linear parts.
	var ta int64 = fx.FxGet(cx, cTm)
	var tb int64 = fx.FxGet(cx, cTm+2)
	var tc int64 = fx.FxGet(cx, cTm+4)
	var td int64 = fx.FxGet(cx, cTm+6)
	var te int64 = fx.FxGet(cx, cTm+8)
	var tf int64 = fx.FxGet(cx, cTm+10)
	var ma int64 = fx.FxGet(cx, cM)
	var mb int64 = fx.FxGet(cx, cM+2)
	var mc int64 = fx.FxGet(cx, cM+4)
	var md int64 = fx.FxGet(cx, cM+6)
	var me int64 = fx.FxGet(cx, cM+8)
	var mf int64 = fx.FxGet(cx, cM+10)
	fx.FxPut(cx, cTm+8, fx.FxClamp(te+(fx.FxMul(dx, ta)+fx.FxMul(dy, tc))))
	fx.FxPut(cx, cTm+10, fx.FxClamp(tf+(fx.FxMul(dx, tb)+fx.FxMul(dy, td))))
	fx.FxPut(cx, cM+8, fx.FxClamp(me+(fx.FxMul(dx, ma)+fx.FxMul(dy, mc))))
	fx.FxPut(cx, cM+10, fx.FxClamp(mf+(fx.FxMul(dx, mb)+fx.FxMul(dy, md))))
	return 0
}

func pcTd(cx *port.Cells, tx int64, ty int64) int32 {
	// Td: the line matrix moves by (tx, ty) in its own space; the text matrix
	// starts over there.
	fx.MxTranslate(cx, cTmp, tx, ty)
	fx.MxMul(cx, cTlm, cTmp, cTlm)
	fx.MxCopy(cx, cTm, cTlm)
	return 0
}

func pcSetTm(cx *port.Cells, a int64, b int64, c int64, d int64, e int64, f int64) int32 {
	fx.MxSet(cx, cTm, a, b, c, d, e, f)
	fx.MxCopy(cx, cTlm, cTm)
	return 0
}

func pcNextLine(cx *port.Cells) int32 {
	// T*: down by the leading.
	var tl int64 = fx.FxGet(cx, cCur+gTl)
	pcTd(cx, int64(0), int64(0)-tl)
	return 0
}

func pcByte(v int64) int32 {
	// A colour component in 0..1 (an Fx) as 0..255, rounded.
	var n int32 = fx.FxRound(fx.FxMul(v, fx.FxOfInt(255)))
	if n < 0 {
		return 0
	}
	if n > 255 {
		return 255
	}
	return n
}

func pcRgb(r int32, g int32, bl int32) int32 {
	return (r * 65536) + ((g * 256) + bl)
}

func pcSetColor(cx *port.Cells, ox *port.Cells, n int32) int32 {
	// sc / scn / g / rg / k: set the fill colour from n operands by their count
	// (1 gray, 3 RGB, 4 CMYK). A component list of another length (a pattern, an
	// Indexed or Separation colour) leaves the colour as it was.
	var o0 int64 = pcNum(ox, n, 0)
	var o1 int64 = pcNum(ox, n, 1)
	var o2 int64 = pcNum(ox, n, 2)
	var o3 int64 = pcNum(ox, n, 3)
	var one int64 = fx.FxOne()
	if n == 1 {
		var gy int32 = pcByte(o0)
		port.CellsSet(cx, cCur+gColor, pcRgb(gy, gy, gy))
		return 0
	}
	if n == 3 {
		port.CellsSet(cx, cCur+gColor, pcRgb(pcByte(o0), pcByte(o1), pcByte(o2)))
		return 0
	}
	if n == 4 {
		var kk int64 = one - o3
		port.CellsSet(cx, cCur+gColor, pcRgb(pcByte(fx.FxMul(one-o0, kk)), pcByte(fx.FxMul(one-o1, kk)), pcByte(fx.FxMul(one-o2, kk))))
		return 0
	}
	return 0
}

func pcDictLookup(ar *port.Cells, dict int32, ox *port.Cells, ns int32, nl int32) int32 {
	// The value (unresolved) under the key spelled ox[ns, ns+nl), or 0. The
	// last of a repeated key wins.
	var k int32 = pdflex.PlFirst(ar, dict)
	var v int32 = 0
	var found int32 = 0
	var same int32 = 0
	var i int32 = 0
	if pdflex.PlKindOf(ar, dict) != 7 {
		return 0
	}
	for k != 0 {
		v = pdflex.PlNext(ar, k)
		if (pdflex.PlKindOf(ar, k) == 4) && (pdflex.PlNameLen(ar, k) == nl) {
			same = 1
			i = 0
			for (same == 1) && (i < nl) {
				if pdflex.PlNameByte(ar, k, i) != port.CellsAt(ox, ns+i) {
					same = 0
				}
				i += 1
			}
			if same == 1 {
				found = v
			}
		}
		if v == 0 {
			k = 0
		} else {
			k = pdflex.PlNext(ar, v)
		}
	}
	return found
}

func pcResEntry(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, ox *port.Cells, kindId int32, ei int32) int32 {
	// The UNRESOLVED entry named by operand ei (a name) in the current Resources'
	// sub-dictionary `kind-id` (`(pn-font)`, `(pn-x-object)`, ...), 0 when none.
	var res int32 = port.CellsAt(cx, cRes)
	var ns int32 = pcEa(ox, ei)
	var nl int32 = pcEb(ox, ei)
	if res == 0 {
		return 0
	}
	var sub int32 = pdfdoc.PdDget(src, ar, dc, a, b, st, res, kindId)
	if sub == 0 {
		return 0
	}
	return pcDictLookup(ar, sub, ox, ns, nl)
}

func pcFLoad(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, out *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, slot int32, fh int32) int32 {
	if slot == 0 {
		return pdffont.PfnLoad(src, ar, dc, a, b, st, f0, out, fh)
	}
	if slot == 1 {
		return pdffont.PfnLoad(src, ar, dc, a, b, st, f1, out, fh)
	}
	if slot == 2 {
		return pdffont.PfnLoad(src, ar, dc, a, b, st, f2, out, fh)
	}
	return pdffont.PfnLoad(src, ar, dc, a, b, st, f3, out, fh)
}

func pcFQ(f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, slot int32, which int32) int32 {
	// A font's metric: which 0 ascent, 1 descent, 2 vertical, 3 DW2 v, 4 DW2 w.
	if slot == 0 {
		if which == 0 {
			return pdffont.PfnAscent(f0)
		}
		if which == 1 {
			return pdffont.PfnDescent(f0)
		}
		if which == 2 {
			return pdffont.PfnVertical(f0)
		}
		if which == 3 {
			return pdffont.PfnDw2V(f0)
		}
		return pdffont.PfnDw2W(f0)
	}
	if slot == 1 {
		if which == 0 {
			return pdffont.PfnAscent(f1)
		}
		if which == 1 {
			return pdffont.PfnDescent(f1)
		}
		if which == 2 {
			return pdffont.PfnVertical(f1)
		}
		if which == 3 {
			return pdffont.PfnDw2V(f1)
		}
		return pdffont.PfnDw2W(f1)
	}
	if slot == 2 {
		if which == 0 {
			return pdffont.PfnAscent(f2)
		}
		if which == 1 {
			return pdffont.PfnDescent(f2)
		}
		if which == 2 {
			return pdffont.PfnVertical(f2)
		}
		if which == 3 {
			return pdffont.PfnDw2V(f2)
		}
		return pdffont.PfnDw2W(f2)
	}
	if which == 0 {
		return pdffont.PfnAscent(f3)
	}
	if which == 1 {
		return pdffont.PfnDescent(f3)
	}
	if which == 2 {
		return pdffont.PfnVertical(f3)
	}
	if which == 3 {
		return pdffont.PfnDw2V(f3)
	}
	return pdffont.PfnDw2W(f3)
}

func pcFCodeLen(f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, slot int32, b0 int32, b1 int32, b2 int32, b3 int32) int32 {
	if slot == 0 {
		return pdffont.PfnCodeLen(f0, b0, b1, b2, b3)
	}
	if slot == 1 {
		return pdffont.PfnCodeLen(f1, b0, b1, b2, b3)
	}
	if slot == 2 {
		return pdffont.PfnCodeLen(f2, b0, b1, b2, b3)
	}
	return pdffont.PfnCodeLen(f3, b0, b1, b2, b3)
}

func pcFMap(f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, slot int32, code int32) int32 {
	// The code points of a code: their count (`pfn-map`).
	if slot == 0 {
		return pdffont.PfnMap(f0, code)
	}
	if slot == 1 {
		return pdffont.PfnMap(f1, code)
	}
	if slot == 2 {
		return pdffont.PfnMap(f2, code)
	}
	return pdffont.PfnMap(f3, code)
}

func pcFCp(f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, slot int32, i int32) int32 {
	if slot == 0 {
		return pdffont.PfnCp(f0, i)
	}
	if slot == 1 {
		return pdffont.PfnCp(f1, i)
	}
	if slot == 2 {
		return pdffont.PfnCp(f2, i)
	}
	return pdffont.PfnCp(f3, i)
}

func pcFHow(f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, slot int32) int32 {
	if slot == 0 {
		return pdffont.PfnHowOf(f0)
	}
	if slot == 1 {
		return pdffont.PfnHowOf(f1)
	}
	if slot == 2 {
		return pdffont.PfnHowOf(f2)
	}
	return pdffont.PfnHowOf(f3)
}

func pcFWidth(f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, slot int32, code int32) int32 {
	if slot == 0 {
		return pdffont.PfnWidth(f0, code)
	}
	if slot == 1 {
		return pdffont.PfnWidth(f1, code)
	}
	if slot == 2 {
		return pdffont.PfnWidth(f2, code)
	}
	return pdffont.PfnWidth(f3, code)
}

func pcFontId(cx *port.Cells, key int32) int32 {
	// The evidence id of a font dictionary: its index in the order the
	// document first showed it (-1 past 512 fonts).
	var n int32 = port.CellsAt(cx, cNfont)
	var i int32 = 0
	for i < n {
		if port.CellsAt(cx, cFids+i) == key {
			return i
		}
		i += 1
	}
	if n >= maxFids {
		return -1
	}
	port.CellsSet(cx, cFids+n, key)
	port.CellsSet(cx, cNfont, n+1)
	return n
}

func pcEnsureFont(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, out *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells) int32 {
	// Make the current font (the graphics state's) resident in a slot and set
	// C_SLOT to it, -1 when there is none. A font is loaded once and kept; the
	// slot that has gone unused longest is the one replaced.
	var key int32 = port.CellsAt(cx, cCur+gFont)
	var i int32 = 0
	var at int32 = 0
	var pick int32 = 0
	var best int32 = 2147483647
	var status int32 = 0
	var fid int32 = 0
	var clock int32 = port.CellsAt(cx, cClock)
	if key == 0 {
		port.CellsSet(cx, cSlot, -1)
		return 0
	}
	clock += 1
	port.CellsSet(cx, cClock, clock)
	for i < 4 {
		at = cSlots + (i * slotStride)
		if port.CellsAt(cx, at+sKey) == key {
			port.CellsSet(cx, at+sUse, clock)
			port.CellsSet(cx, cSlot, i)
			return 0
		}
		if port.CellsAt(cx, at+sUse) < best {
			best = port.CellsAt(cx, at+sUse)
			pick = i
		}
		i += 1
	}
	at = cSlots + (pick * slotStride)
	status = pcFLoad(src, ar, dc, a, b, st, out, f0, f1, f2, f3, pick, key)
	if pdfsrc.PsMissed(src) {
		port.CellsSet(cx, cAbort, 1)
		port.CellsSet(cx, at+sKey, 0)
		port.CellsSet(cx, cSlot, -1)
		return 0
	}
	port.CellsSet(cx, at+sKey, key)
	port.CellsSet(cx, at+sUse, clock)
	port.CellsSet(cx, at+sStatus, status)
	fid = pcFontId(cx, key)
	port.CellsSet(cx, at+sId, fid)
	if status == 0 {
		port.CellsSet(cx, at+sAsc, pcFQ(f0, f1, f2, f3, pick, 0))
		port.CellsSet(cx, at+sDesc, pcFQ(f0, f1, f2, f3, pick, 1))
		port.CellsSet(cx, at+sVert, pcFQ(f0, f1, f2, f3, pick, 2))
		port.CellsSet(cx, at+sDw2v, pcFQ(f0, f1, f2, f3, pick, 3))
		port.CellsSet(cx, at+sDw2w, pcFQ(f0, f1, f2, f3, pick, 4))
	} else {
		port.CellsSet(cx, at+sAsc, 0)
		port.CellsSet(cx, at+sDesc, 0)
		port.CellsSet(cx, at+sVert, 0)
	}
	port.CellsSet(cx, cSlot, pick)
	return 0
}

func pcTf(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, ox *port.Cells, n int32) int32 {
	// Tf: the font named by operand 0 from the current Resources, at the size of
	// operand 1. The dictionary is resolved here and loaded at the first glyph.
	var size int64 = pcNum(ox, n, 1)
	var fh int32 = 0
	var raw int32 = 0
	fx.FxPut(cx, cCur+gFs, size)
	if (n >= 1) && (pcKind(ox, 0) == kName) {
		raw = pcResEntry(src, ar, dc, a, b, st, cx, ox, pdfnames.PnFont(), 0)
		if raw != 0 {
			fh = pdfdoc.PdResolve(src, ar, dc, a, b, st, raw)
		}
	}
	if pdfsrc.PsMissed(src) {
		port.CellsSet(cx, cAbort, 1)
		return 0
	}
	if fh == 0 {
		pcWarnSet(cx, wFont)
	} else if pdflex.PlKindOf(ar, fh) != 7 {
		fh = 0
		pcWarnSet(cx, wFont)
	}
	port.CellsSet(cx, cCur+gFont, fh)
	return 0
}

func pcMin4(p int64, q int64, r int64, s int64) int64 {
	var m int64 = p
	if q < m {
		m = q
	}
	if r < m {
		m = r
	}
	if s < m {
		m = s
	}
	return m
}

func pcMax4(p int64, q int64, r int64, s int64) int64 {
	var m int64 = p
	if q > m {
		m = q
	}
	if r > m {
		m = r
	}
	if s > m {
		m = s
	}
	return m
}

func pcGlyph(cx *port.Cells, gl *port.Cells, et *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, code int32, ncode int32) int32 {
	// One shown glyph: look the code up, put its cell in page space, record it,
	// advance the text position by its width, the character and word spacing.
	var slot int32 = port.CellsAt(cx, cSlot)
	var fs int64 = fx.FxGet(cx, cCur+gFs)
	var th int64 = fx.FxGet(cx, cCur+gTh)
	var tc int64 = fx.FxGet(cx, cCur+gTc)
	var tw int64 = fx.FxGet(cx, cCur+gTw)
	var rise int64 = fx.FxGet(cx, cCur+gRise)
	var sat int32 = 0
	var cnt int32 = 0
	var cp0 int32 = -1
	var how int32 = 5
	var w int32 = -1
	var asc int32 = 0
	var desc int32 = 0
	var vert int32 = 0
	var dwv int32 = -100000
	var fid int32 = -1
	var tstart int32 = -1
	var i int32 = 0
	var idx int32 = 0
	if slot >= 0 {
		sat = cSlots + (slot * slotStride)
		fid = port.CellsAt(cx, sat+sId)
		if port.CellsAt(cx, sat+sStatus) == 0 {
			cnt = pcFMap(f0, f1, f2, f3, slot, code)
			how = pcFHow(f0, f1, f2, f3, slot)
			w = pcFWidth(f0, f1, f2, f3, slot, code)
			asc = port.CellsAt(cx, sat+sAsc)
			desc = port.CellsAt(cx, sat+sDesc)
			vert = port.CellsAt(cx, sat+sVert)
			dwv = port.CellsAt(cx, sat+sDw2w)
		}
	}
	if cnt > 0 {
		cp0 = pcFCp(f0, f1, f2, f3, slot, 0)
	}
	// A composite font's ToUnicode may say U+0000 or U+FFFD for a glyph it has no value
	// for (Skia does, for the parts of a Devanagari conjunct): that is no value.
	if (cnt == 1) && ((cp0 == 0) || (cp0 == 65533)) {
		cnt = 0
		cp0 = -1
		how = 5
	}
	if w < 0 {
		w = 50000
		pcWarnSet(cx, wWidth)
	}
	if (asc == 0) && (desc == 0) {
		asc = 800
		desc = -200
	}
	var wfx int64 = fx.FxMuldiv(int64(w), fs, int64(100000))
	var x0t int64 = int64(0)
	var x1t int64 = int64(0)
	var y0t int64 = int64(0)
	var y1t int64 = int64(0)
	if vert == 0 {
		x1t = fx.FxMul(wfx, th)
		y0t = fx.FxMuldiv(int64(desc), fs, int64(1000)) + rise
		y1t = fx.FxMuldiv(int64(asc), fs, int64(1000)) + rise
	} else {
		x0t = int64(0) - (wfx / int64(2))
		x1t = wfx / int64(2)
		y0t = fx.FxMuldiv(int64(dwv), fs, int64(100000)) + rise
		y1t = rise
	}
	var p0x int64 = fx.MxX(cx, cM, x0t, y0t)
	var p0y int64 = fx.MxY(cx, cM, x0t, y0t)
	var p1x int64 = fx.MxX(cx, cM, x1t, y0t)
	var p1y int64 = fx.MxY(cx, cM, x1t, y0t)
	var p2x int64 = fx.MxX(cx, cM, x0t, y1t)
	var p2y int64 = fx.MxY(cx, cM, x0t, y1t)
	var p3x int64 = fx.MxX(cx, cM, x1t, y1t)
	var p3y int64 = fx.MxY(cx, cM, x1t, y1t)
	var ma int64 = fx.FxGet(cx, cM)
	var mb int64 = fx.FxGet(cx, cM+2)
	var mc int64 = fx.FxGet(cx, cM+4)
	var md int64 = fx.FxGet(cx, cM+6)
	var size int32 = fx.FxRound(fx.FxMul(fx.FxHypot(mc, md), fx.FxAbs(fs)))
	var rot int32 = fx.FxAtan2(int64(0)-mb, ma)
	var bline int32 = fx.FxRound(fx.MxY(cx, cM, int64(0), rise))
	var g int32 = evidence.GlNew(gl, port.CellsAt(cx, cPage), cp0, fid, size, fx.FxRound(pcMin4(p0x, p1x, p2x, p3x)), fx.FxRound(pcMin4(p0y, p1y, p2y, p3y)), fx.FxRound(pcMax4(p0x, p1x, p2x, p3x)), fx.FxRound(pcMax4(p0y, p1y, p2y, p3y)))
	evidence.GlSet(gl, g, evidence.GfHow(), how)
	evidence.GlSet(gl, g, evidence.GfBaseline(), bline)
	evidence.GlSet(gl, g, evidence.GfRot(), rot)
	evidence.GlSet(gl, g, evidence.GfColor(), port.CellsAt(cx, cCur+gColor))
	evidence.GlSet(gl, g, evidence.GfAlpha(), port.CellsAt(cx, cCur+gAlpha))
	evidence.GlSet(gl, g, evidence.GfMode(), port.CellsAt(cx, cCur+gMode))
	evidence.GlSet(gl, g, evidence.GfArtifact(), port.CellsAt(cx, cCurart))
	evidence.GlSet(gl, g, evidence.GfMcid(), port.CellsAt(cx, cCurmcid))
	if cnt > 1 {
		i = 0
		for i < cnt {
			idx = evidence.EtxAppendCp(et, pcFCp(f0, f1, f2, f3, slot, i))
			if i == 0 {
				tstart = idx
			}
			i += 1
		}
		evidence.GlSet(gl, g, evidence.GfTstart(), tstart)
		evidence.GlSet(gl, g, evidence.GfTlen(), cnt)
	}
	// The advance: tx = (w0 * Tfs + Tc + Tw) * Th, or ty = w1 * Tfs + Tc + Tw.
	var adv int64 = int64(0)
	if vert == 0 {
		adv = wfx + tc
	} else {
		adv = fx.FxMuldiv(int64(dwv), fs, int64(100000)) + tc
	}
	if (code == 32) && (ncode == 1) {
		adv = adv + tw
	}
	if vert == 0 {
		pcAdvance(cx, fx.FxMul(adv, th), int64(0))
	} else {
		pcAdvance(cx, int64(0), adv)
	}
	return 0
}

func pcShowStr(cx *port.Cells, ox *port.Cells, gl *port.Cells, et *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, s int32) int32 {
	// Show the string operand s: split it into codes by the font's codespace.
	var start int32 = pcEa(ox, s)
	var ln int32 = pcEb(ox, s)
	var slot int32 = port.CellsAt(cx, cSlot)
	var okfont int32 = 0
	var i int32 = 0
	var n int32 = 1
	var code int32 = 0
	var k int32 = 0
	var b0 int32 = 0
	var b1 int32 = -1
	var b2 int32 = -1
	var b3 int32 = -1
	if slot >= 0 {
		if port.CellsAt(cx, (cSlots+(slot*slotStride))+sStatus) == 0 {
			okfont = 1
		}
	}
	for i < ln {
		b0 = port.CellsAt(ox, start+i)
		b1 = -1
		b2 = -1
		b3 = -1
		if (i + 1) < ln {
			b1 = port.CellsAt(ox, start+(i+1))
		}
		if (i + 2) < ln {
			b2 = port.CellsAt(ox, start+(i+2))
		}
		if (i + 3) < ln {
			b3 = port.CellsAt(ox, start+(i+3))
		}
		n = 1
		if okfont == 1 {
			n = pcFCodeLen(f0, f1, f2, f3, slot, b0, b1, b2, b3)
		}
		if n < 1 {
			n = 1
		}
		if n > 4 {
			n = 4
		}
		if (i + n) > ln {
			n = ln - i
		}
		code = 0
		k = 0
		for k < n {
			if (n == 4) && ((k == 0) && (port.CellsAt(ox, start+i) >= 128)) {
				code = (port.CellsAt(ox, start+i) - 256) * 16777216
			} else {
				code = (code * 256) + port.CellsAt(ox, start+(i+k))
			}
			k += 1
		}
		pcGlyph(cx, gl, et, f0, f1, f2, f3, code, n)
		i += n
	}
	return 0
}

func pcShowArr(cx *port.Cells, ox *port.Cells, gl *port.Cells, et *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, s int32) int32 {
	// TJ: strings and adjustments. An adjustment n moves the position by
	// -n/1000 of the font size (along x, scaled by Th; along y in vertical mode).
	var cnt int32 = pcEa(ox, s)
	var slot int32 = port.CellsAt(cx, cSlot)
	var fs int64 = fx.FxGet(cx, cCur+gFs)
	var th int64 = fx.FxGet(cx, cCur+gTh)
	var vert int32 = 0
	var j int32 = s + 1
	var k int32 = 0
	var delta int64 = int64(0)
	if slot >= 0 {
		vert = port.CellsAt(cx, (cSlots+(slot*slotStride))+sVert)
	}
	for j < ((s + 1) + cnt) {
		k = pcKind(ox, j)
		if k == kStr {
			pcShowStr(cx, ox, gl, et, f0, f1, f2, f3, j)
		}
		if k == kNum {
			delta = int64(0) - fx.FxMuldiv(fx.FxMul(fx.FxJoin(pcEa(ox, j), pcEb(ox, j)), fs), int64(1), int64(1000))
			if vert == 0 {
				pcAdvance(cx, fx.FxMul(delta, th), int64(0))
			} else {
				pcAdvance(cx, int64(0), delta)
			}
		}
		j += pcEsize(ox, j)
	}
	return 0
}

var pcPdfdocTab [41]int32 = [41]int32{
	728, 711, 710, 729, 733, 731, 730, 732, 8226, 8224, 8225, 8230, 8212, 8211, 402, 8260,
	8249, 8250, 8722, 8240, 8222, 8220, 8221, 8216, 8217, 8218, 8482, 64257, 64258, 321, 338, 352,
	376, 381, 305, 322, 339, 353, 382, 65533, 8364,
}

func pcPdfdoc(c int32) int32 {
	// PDFDocEncoding (Annex D.2) to Unicode: Latin-1 except 0x18-0x1F, 0x80-0xA0.
	if (c >= 24) && (c <= 31) {
		return pcPdfdocTab[c-24]
	}
	if (c >= 128) && (c <= 160) {
		return pcPdfdocTab[8+(c-128)]
	}
	return c
}

func pcPushBytes(et *port.Cells, ox *port.Cells, start int32, ln int32) int32 {
	// A name's bytes as code points (Latin-1), into the evidence text. Answers
	// the index of the first.
	var at int32 = port.CellsLen(et)
	var k int32 = 0
	for k < ln {
		evidence.EtxAppendCp(et, port.CellsAt(ox, start+k))
		k += 1
	}
	return at
}

func pcPushEntry(et *port.Cells, ox *port.Cells, i int32) int32 {
	// The bytes of name operand i into the evidence text; the index of the first.
	var s int32 = pcEa(ox, i)
	var ln int32 = pcEb(ox, i)
	return pcPushBytes(et, ox, s, ln)
}

func pcPushUtf16(et *port.Cells, ox *port.Cells, start int32, ln int32, little int32) int32 {
	// UTF-16 text from ox[start, start+ln) (after the byte order mark), into
	// the evidence text: surrogate pairs joined, a lone surrogate U+FFFD, and
	// the language escapes of PDF 2.0 (U+001B ... U+001B) dropped.
	var k int32 = 0
	var u int32 = 0
	var u2 int32 = 0
	var skip int32 = 0
	for (k + 1) < ln {
		if little == 1 {
			u = port.CellsAt(ox, start+k) + (port.CellsAt(ox, start+(k+1)) * 256)
		} else {
			u = (port.CellsAt(ox, start+k) * 256) + port.CellsAt(ox, start+(k+1))
		}
		k += 2
		if (u >= 55296) && (u <= 56319) && ((k + 1) < ln) {
			if little == 1 {
				u2 = port.CellsAt(ox, start+k) + (port.CellsAt(ox, start+(k+1)) * 256)
			} else {
				u2 = (port.CellsAt(ox, start+k) * 256) + port.CellsAt(ox, start+(k+1))
			}
			if (u2 >= 56320) && (u2 <= 57343) {
				u = 65536 + (((u - 55296) * 1024) + (u2 - 56320))
				k += 2
			}
		}
		if u == 27 {
			skip = 1 - skip
		} else if skip == 0 {
			evidence.EtxAppendCp(et, u)
		}
	}
	return 0
}

func pcPushUtf8(et *port.Cells, ox *port.Cells, start int32, ln int32) int32 {
	var k int32 = 0
	var c int32 = 0
	var need int32 = 0
	var v int32 = 0
	var j int32 = 0
	var ok int32 = 0
	for k < ln {
		c = port.CellsAt(ox, start+k)
		k += 1
		need = 0
		v = c
		if c >= 240 {
			need = 3
			v = c - 240
		} else if c >= 224 {
			need = 2
			v = c - 224
		} else if c >= 192 {
			need = 1
			v = c - 192
		}
		ok = 1
		if (c >= 128) && (c < 192) {
			ok = 0
		}
		if c > 247 {
			ok = 0
		}
		j = 0
		for (ok == 1) && (j < need) {
			if (k < ln) && ((port.CellsAt(ox, start+k) >= 128) && (port.CellsAt(ox, start+k) < 192)) {
				v = (v * 64) + (port.CellsAt(ox, start+k) - 128)
				k += 1
			} else {
				ok = 0
			}
			j += 1
		}
		if ok == 1 {
			evidence.EtxAppendCp(et, v)
		} else {
			evidence.EtxAppendCp(et, 65533)
		}
	}
	return 0
}

func pcPushText(et *port.Cells, ox *port.Cells, start int32, ln int32) int32 {
	// A PDF text string (UTF-16BE or LE with a byte order mark, UTF-8 with its
	// BOM, else PDFDocEncoding) into the evidence text. Answers the first index.
	var at int32 = port.CellsLen(et)
	var k int32 = 0
	if (ln >= 2) && ((port.CellsAt(ox, start) == 254) && (port.CellsAt(ox, start+1) == 255)) {
		pcPushUtf16(et, ox, start+2, ln-2, 0)
		return at
	}
	if (ln >= 2) && ((port.CellsAt(ox, start) == 255) && (port.CellsAt(ox, start+1) == 254)) {
		pcPushUtf16(et, ox, start+2, ln-2, 1)
		return at
	}
	if (ln >= 3) && ((port.CellsAt(ox, start) == 239) && ((port.CellsAt(ox, start+1) == 187) && (port.CellsAt(ox, start+2) == 191))) {
		pcPushUtf8(et, ox, start+3, ln-3)
		return at
	}
	for k < ln {
		evidence.EtxAppendCp(et, pcPdfdoc(port.CellsAt(ox, start+k)))
		k += 1
	}
	return at
}

func pcArFx64(ar *port.Cells, h int32) int64 {
	var kind int32 = pdflex.PlKindOf(ar, h)
	if kind == 2 {
		return fx.FxOfInt(pdflex.PlIntValue(ar, h))
	}
	if kind == 3 {
		return fx.FxOfReal(pdflex.PlIntValue(ar, h), pdflex.PlRefGen(ar, h))
	}
	return int64(0)
}

func pcIngestProps(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, ox *port.Cells, dict int32) int32 {
	// Copy the pairs of a /Properties dictionary that marked content reads
	// into the operand entries as a dictionary entry, so one reader serves an
	// inline property list and a named one. Answers the entry's index.
	var d int32 = pcOxPush(cx, ox, kDict, 0, 0, 0)
	var k int32 = pdflex.PlFirst(ar, dict)
	var v int32 = 0
	var vr int32 = 0
	var want int32 = 0
	var kind int32 = 0
	var at int32 = 0
	var j int32 = 0
	var ln int32 = 0
	var fxv int64 = int64(0)
	if d < 0 {
		return -1
	}
	for k != 0 {
		v = pdflex.PlNext(ar, k)
		want = 0
		if pdflex.PlKindOf(ar, k) == 4 {
			if (pdflex.PlNameIs(ar, k, pdfnames.PnMcid()) == 1) || ((pdflex.PlNameIs(ar, k, pdfnames.PnActualText()) == 1) || ((pdflex.PlNameIs(ar, k, pdfnames.PnAlt()) == 1) || ((pdflex.PlNameIs(ar, k, pdfnames.PnE()) == 1) || ((pdflex.PlNameIs(ar, k, pdfnames.PnLang()) == 1) || ((pdflex.PlNameIs(ar, k, pdfnames.PnType()) == 1) || (pdflex.PlNameIs(ar, k, pdfnames.PnSubtype()) == 1)))))) {
				want = 1
			}
		}
		if (want == 1) && (v != 0) {
			vr = pdfdoc.PdResolve(src, ar, dc, a, b, st, v)
			kind = 0
			if vr != 0 {
				kind = pdflex.PlKindOf(ar, vr)
			}
			if (kind == 2) || (kind == 3) {
				fxv = pcArFx64(ar, vr)
				// The key, then the number.
				ln = pdflex.PlNameLen(ar, k)
				at = port.CellsLen(ox)
				j = 0
				for j < ln {
					port.CellsPush(ox, pdflex.PlNameByte(ar, k, j))
					j += 1
				}
				pcOxPush(cx, ox, kName, at, ln, 0)
				pcOxPush(cx, ox, kNum, fx.FxHi(fxv), fx.FxLo(fxv), 1)
			}
			if (kind == 4) || (kind == 5) {
				ln = pdflex.PlNameLen(ar, k)
				at = port.CellsLen(ox)
				j = 0
				for j < ln {
					port.CellsPush(ox, pdflex.PlNameByte(ar, k, j))
					j += 1
				}
				pcOxPush(cx, ox, kName, at, ln, 0)
				ln = pdflex.PlStrLen(ar, vr)
				at = port.CellsLen(ox)
				j = 0
				if kind == 4 {
					for j < ln {
						port.CellsPush(ox, pdflex.PlNameByte(ar, vr, j))
						j += 1
					}
				} else {
					for j < ln {
						port.CellsPush(ox, pdflex.PlStrByte(ar, vr, j))
						j += 1
					}
				}
				if kind == 4 {
					pcOxPush(cx, ox, kName, at, ln, 0)
				} else {
					pcOxPush(cx, ox, kStr, at, ln, 0)
				}
			}
		}
		if v == 0 {
			k = 0
		} else {
			k = pdflex.PlNext(ar, v)
		}
	}
	port.CellsSet(ox, (d*4)+1, (port.CellsAt(cx, cOxn)-d)-1)
	return d
}

func pcReadProps(et *port.Cells, sp *port.Cells, ox *port.Cells, span int32, d int32) int32 {
	// Fill the span's fields from the dictionary entry d of the operands: MCID,
	// Type, Subtype, ActualText, Alt, E, Lang. Answers a code for the artifact's
	// class: 1 watermark, 2 background, 3 pagination, 4 layout, 5 another
	// named type or subtype, 0 none.
	var end int32 = (d + 1) + pcEa(ox, d)
	var j int32 = d + 1
	var v int32 = 0
	var ks int32 = 0
	var kl int32 = 0
	var vs int32 = 0
	var vl int32 = 0
	var vk int32 = 0
	var at int32 = 0
	var cls int32 = 0
	for j < end {
		v = j + 1
		if (pcKind(ox, j) == kName) && (v < end) {
			ks = pcEa(ox, j)
			kl = pcEb(ox, j)
			vk = pcKind(ox, v)
			vs = pcEa(ox, v)
			vl = pcEb(ox, v)
			if (pcNameEq(ox, ks, kl, pdfnames.PnMcid()) == 1) && (vk == kNum) {
				evidence.SpSet(sp, span, evidence.SfMcid(), fx.FxRound(fx.FxJoin(vs, vl)))
			}
			if (pcNameEq(ox, ks, kl, pdfnames.PnType()) == 1) && (vk == kName) {
				at = pcPushBytes(et, ox, vs, vl)
				evidence.SpSet(sp, span, evidence.SfType(), at)
				evidence.SpSet(sp, span, evidence.SfTypelen(), vl)
				if pcNameEq(ox, vs, vl, pdfnames.PnPagination()) == 1 {
					if cls == 0 {
						cls = 3
					}
				}
				if pcNameEq(ox, vs, vl, pdfnames.PnLayout()) == 1 {
					if cls == 0 {
						cls = 4
					}
				}
				if pcNameEq(ox, vs, vl, pdfnames.PnBackground()) == 1 {
					if cls != 1 {
						cls = 2
					}
				}
				if cls == 0 {
					cls = 5
				}
			}
			if (pcNameEq(ox, ks, kl, pdfnames.PnSubtype()) == 1) && (vk == kName) {
				at = pcPushBytes(et, ox, vs, vl)
				evidence.SpSet(sp, span, evidence.SfSubtype(), at)
				evidence.SpSet(sp, span, evidence.SfSubtypelen(), vl)
				if pcNameEq(ox, vs, vl, pdfnames.PnWatermark()) == 1 {
					cls = 1
				}
				if pcNameEq(ox, vs, vl, pdfnames.PnBackground()) == 1 {
					if cls != 1 {
						cls = 2
					}
				}
				if (pcNameEq(ox, vs, vl, pdfnames.PnHeader()) == 1) || (pcNameEq(ox, vs, vl, pdfnames.PnFooter()) == 1) {
					if (cls == 0) || (cls == 5) {
						cls = 3
					}
				}
				if cls == 0 {
					cls = 5
				}
			}
			if (vk == kStr) || (vk == kName) {
				if pcNameEq(ox, ks, kl, pdfnames.PnActualText()) == 1 {
					at = pcPushText(et, ox, vs, vl)
					evidence.SpSet(sp, span, evidence.SfActual(), at)
					evidence.SpSet(sp, span, evidence.SfActuallen(), port.CellsLen(et)-at)
				}
				if pcNameEq(ox, ks, kl, pdfnames.PnAlt()) == 1 {
					at = pcPushText(et, ox, vs, vl)
					evidence.SpSet(sp, span, evidence.SfAlt(), at)
					evidence.SpSet(sp, span, evidence.SfAltlen(), port.CellsLen(et)-at)
				}
				if pcNameEq(ox, ks, kl, pdfnames.PnE()) == 1 {
					at = pcPushText(et, ox, vs, vl)
					evidence.SpSet(sp, span, evidence.SfExp(), at)
					evidence.SpSet(sp, span, evidence.SfExplen(), port.CellsLen(et)-at)
				}
				if pcNameEq(ox, ks, kl, pdfnames.PnLang()) == 1 {
					at = pcPushText(et, ox, vs, vl)
					evidence.SpSet(sp, span, evidence.SfLang(), at)
					evidence.SpSet(sp, span, evidence.SfLanglen(), port.CellsLen(et)-at)
				}
			}
			j = v + pcEsize(ox, v)
		} else {
			j += pcEsize(ox, j)
		}
	}
	return cls
}

func pcMcRecompute(cx *port.Cells, sp *port.Cells) int32 {
	// The innermost MCID and artifact class in force: walk the open spans.
	var t int32 = port.CellsAt(cx, cMctop)
	var mcid int32 = -1
	var art int32 = 0
	var guard int32 = 0
	var m int32 = 0
	for (t >= 0) && (guard <= maxMc) {
		if mcid < 0 {
			m = evidence.SpGet(sp, t, evidence.SfMcid())
			if m >= 0 {
				mcid = m
			}
		}
		if art == 0 {
			art = evidence.SpGet(sp, t, evidence.SfArtifact())
		}
		t = evidence.SpGet(sp, t, evidence.SfParent())
		guard += 1
	}
	port.CellsSet(cx, cCurmcid, mcid)
	port.CellsSet(cx, cCurart, art)
	return 0
}

func pcMcPop(cx *port.Cells, sp *port.Cells, gl *port.Cells, unterminated int32) int32 {
	// Close the innermost open span: its glyphs are those shown since it opened.
	var t int32 = port.CellsAt(cx, cMctop)
	if t < 0 {
		return 0
	}
	var g int32 = evidence.GlCount(gl)
	var gf int32 = evidence.SpGet(sp, t, evidence.SfGfirst())
	var par int32 = evidence.SpGet(sp, t, evidence.SfParent())
	evidence.SpSet(sp, t, evidence.SfGcount(), g-gf)
	if unterminated == 1 {
		var fl int32 = evidence.SpGet(sp, t, evidence.SfFlags())
		evidence.SpSet(sp, t, evidence.SfFlags(), fl|evidence.McUnterminated())
	}
	port.CellsSet(cx, cMctop, par)
	port.CellsSet(cx, cMcdepth, port.CellsAt(cx, cMcdepth)-1)
	pcMcRecompute(cx, sp)
	return 0
}

func pcMcBegin(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, ox *port.Cells, gl *port.Cells, et *port.Cells, sp *port.Cells, n int32, props int32) int32 {
	// BMC / BDC: open a span with the tag of operand 0 and, for BDC, the
	// properties of operand 1 (an inline dictionary, or a name in /Properties).
	var depth int32 = port.CellsAt(cx, cMcdepth)
	var tstart int32 = 0
	var tlen int32 = 0
	var span int32 = 0
	var d int32 = -1
	var cls int32 = 0
	var raw int32 = 0
	var dh int32 = 0
	var isart int32 = 0
	var flags int32 = 0
	if depth >= maxMc {
		port.CellsSet(cx, cMcover, port.CellsAt(cx, cMcover)+1)
		pcWarnSet(cx, wMc)
		return 0
	}
	tstart = port.CellsLen(et)
	if (n >= 1) && (pcKind(ox, 0) == kName) {
		tstart = pcPushEntry(et, ox, 0)
		tlen = pcEb(ox, 0)
		if pcEntryNameIs(ox, 0, pdfnames.PnArtifact()) == 1 {
			isart = 1
		}
	}
	span = evidence.SpNew(sp, port.CellsAt(cx, cPage), tstart, tlen, port.CellsAt(cx, cMctop), evidence.GlCount(gl))
	evidence.SpSet(sp, span, evidence.SfStm(), port.CellsAt(cx, cStm))
	if isart == 1 {
		evidence.SpSet(sp, span, evidence.SfArtifact(), evidence.ArOther())
	}
	if (props == 1) && (n >= 2) {
		if pcKind(ox, 1) == kDict {
			d = 1
			flags = evidence.McInline()
		}
		if pcKind(ox, 1) == kName {
			raw = pcResEntry(src, ar, dc, a, b, st, cx, ox, pdfnames.PnProperties(), 1)
			if raw != 0 {
				dh = pdfdoc.PdResolve(src, ar, dc, a, b, st, raw)
			}
			if pdfsrc.PsMissed(src) {
				port.CellsSet(cx, cAbort, 1)
			}
			if (dh != 0) && (pdflex.PlKindOf(ar, dh) == 7) {
				d = pcIngestProps(src, ar, dc, a, b, st, cx, ox, dh)
				flags = evidence.McResource()
			} else {
				flags = evidence.McUnresolved()
				pcWarnSet(cx, wProps)
			}
		}
		evidence.SpSet(sp, span, evidence.SfFlags(), flags)
		if d >= 0 {
			cls = pcReadProps(et, sp, ox, span, d)
			if isart == 1 {
				if cls == 1 {
					evidence.SpSet(sp, span, evidence.SfArtifact(), evidence.ArWatermark())
				}
				if cls == 2 {
					evidence.SpSet(sp, span, evidence.SfArtifact(), evidence.ArBackground())
				}
				if cls == 3 {
					evidence.SpSet(sp, span, evidence.SfArtifact(), evidence.ArPagination())
				}
				if cls == 4 {
					evidence.SpSet(sp, span, evidence.SfArtifact(), evidence.ArLayout())
				}
			}
		}
	}
	port.CellsSet(cx, cMctop, span)
	port.CellsSet(cx, cMcdepth, depth+1)
	pcMcRecompute(cx, sp)
	return 0
}

func pcMcEnd(cx *port.Cells, sp *port.Cells, gl *port.Cells) int32 {
	// EMC: close the innermost span this stream opened; a BDC that was too deep
	// to record is balanced first; an EMC with nothing to close is ignored.
	var over int32 = port.CellsAt(cx, cMcover)
	if over > 0 {
		port.CellsSet(cx, cMcover, over-1)
		return 0
	}
	if port.CellsAt(cx, cMcdepth) <= port.CellsAt(cx, cMcbase) {
		pcWarnSet(cx, wMc)
		return 0
	}
	return pcMcPop(cx, sp, gl, 0)
}

func pcSkipInline(cx *port.Cells, cs *port.Cells) int32 {
	// BI: skip to the end of the inline image: find `ID` and its one white
	// space, then the first `EI` that stands alone (white space before and white
	// space or the end after). Binary data rarely contains one; if it does the
	// rest is read as operators and skipped as unknown ones.
	var end int32 = port.CellsAt(cx, cEnd)
	var p int32 = port.CellsAt(cx, cPos)
	var found int32 = 0
	for ((p + 2) < end) && (found == 0) {
		if (pcWs(port.CellsAt(cs, p)) == 1) && ((port.CellsAt(cs, p+1) == 73) && ((port.CellsAt(cs, p+2) == 68) && (((p + 3) >= end) || (pcWs(port.CellsAt(cs, p+3)) == 1)))) {
			found = 1
			p += 4
		} else {
			p += 1
		}
	}
	if found == 0 {
		port.CellsSet(cx, cPos, end)
		return 0
	}
	found = 0
	for ((p + 1) < end) && (found == 0) {
		if (port.CellsAt(cs, p) == 69) && ((port.CellsAt(cs, p+1) == 73) && (((p == 0) || (pcWs(port.CellsAt(cs, p-1)) == 1)) && (((p + 2) >= end) || (pcWs(port.CellsAt(cs, p+2)) == 1)))) {
			found = 1
			p += 2
		} else {
			p += 1
		}
	}
	if found == 0 {
		p = end
	}
	port.CellsSet(cx, cPos, p)
	return 0
}

func pcAppendStream(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, out *port.Cells, cs *port.Cells, sh int32) int32 {
	// Decode stream sh and append its bytes (and a line feed) to `cs`. Answers
	// the filter chain's status (0 ok), or -1 when the source missed.
	var status int32 = pdfdoc.PdStreamData(src, ar, dc, a, b, st, sh, out)
	var n int32 = port.CellsLen(out)
	var i int32 = 0
	if pdfsrc.PsMissed(src) {
		port.CellsSet(cx, cAbort, 1)
		return -1
	}
	if status != 0 {
		pcWarnSet(cx, wStream)
		port.CellsSet(cx, cSstat, status)
	}
	for i < n {
		port.CellsPush(cs, port.CellsAt(out, i))
		i += 1
	}
	port.CellsPush(cs, 10)
	return status
}

func pcDo(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, ox *port.Cells, cs *port.Cells, out *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, gl *port.Cells, et *port.Cells, sp *port.Cells, n int32) int32 {
	// Do: run the Form XObject named by operand 0. Images and everything that is
	// not a form are skipped. The form's /Matrix is concatenated to the CTM, its
	// /Resources replace the current ones (else they are inherited), and it runs
	// inside its own `q`/`Q`.
	if n < 1 {
		return 0
	}
	if pcKind(ox, 0) != kName {
		return 0
	}
	var raw int32 = pcResEntry(src, ar, dc, a, b, st, cx, ox, pdfnames.PnXObject(), 0)
	var objnum int32 = 0
	var xh int32 = 0
	var sub int32 = 0
	var fd int32 = 0
	var i int32 = 0
	var mat int32 = 0
	var el int32 = 0
	var got int32 = 0
	var res int32 = 0
	var oldres int32 = 0
	var oldstm int32 = 0
	var start int32 = 0
	var endcs int32 = 0
	var status int32 = 0
	if pdfsrc.PsMissed(src) {
		port.CellsSet(cx, cAbort, 1)
		return 0
	}
	if raw == 0 {
		pcWarnSet(cx, wForm)
		return 0
	}
	if pdflex.PlKindOf(ar, raw) == 9 {
		objnum = pdflex.PlIntValue(ar, raw)
	}
	xh = pdfdoc.PdResolve(src, ar, dc, a, b, st, raw)
	if pdfsrc.PsMissed(src) {
		port.CellsSet(cx, cAbort, 1)
		return 0
	}
	if xh == 0 {
		pcWarnSet(cx, wForm)
		return 0
	}
	if pdflex.PlKindOf(ar, xh) != 8 {
		return 0
	}
	sub = pdfdoc.PdDget(src, ar, dc, a, b, st, xh, pdfnames.PnSubtype())
	if pdfsrc.PsMissed(src) {
		port.CellsSet(cx, cAbort, 1)
		return 0
	}
	if sub == 0 {
		return 0
	}
	if pdflex.PlNameIs(ar, sub, pdfnames.PnForm()) == 0 {
		return 0
	}
	// Depth and cycles: a form deeper than FORM_DEPTH, or already running, is skipped.
	fd = port.CellsAt(cx, cFdepth)
	if (fd >= maxForms) || (fd >= port.CellsAt(cx, cFlim)) {
		pcWarnSet(cx, wDepth)
		return 0
	}
	if objnum != 0 {
		for i < fd {
			if port.CellsAt(cx, cFstack+i) == objnum {
				pcWarnSet(cx, wDepth)
				return 0
			}
			i += 1
		}
	}
	// Its /Matrix (six numbers, else the identity).
	fx.MxIdent(cx, cTmp)
	mat = pdfdoc.PdDget(src, ar, dc, a, b, st, xh, pdfnames.PnMatrix())
	if (mat != 0) && (pdflex.PlKindOf(ar, mat) == 6) {
		el = pdflex.PlFirst(ar, mat)
		got = 0
		for (el != 0) && (got < 6) {
			fx.FxPut(cx, cTmp+(got*2), pcArFx64(ar, el))
			el = pdflex.PlNext(ar, el)
			got += 1
		}
		if got < 6 {
			fx.MxIdent(cx, cTmp)
		}
	}
	res = pdfdoc.PdDget(src, ar, dc, a, b, st, xh, pdfnames.PnResources())
	oldres = port.CellsAt(cx, cRes)
	oldstm = port.CellsAt(cx, cStm)
	if (res != 0) && (pdflex.PlKindOf(ar, res) == 7) {
		port.CellsSet(cx, cRes, res)
	}
	start = port.CellsLen(cs)
	status = pcAppendStream(src, ar, dc, a, b, st, cx, out, cs, xh)
	if status == -1 {
		return 0
	}
	pcSave(cx)
	fx.MxMul(cx, cCur+gCtm, cTmp, cCur+gCtm)
	port.CellsSet(cx, cFstack+fd, objnum)
	port.CellsSet(cx, cFdepth, fd+1)
	port.CellsSet(cx, cStm, objnum)
	endcs = port.CellsLen(cs)
	pcRun(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, sp, start, endcs)
	port.CellsSet(cx, cFdepth, fd)
	port.CellsSet(cx, cStm, oldstm)
	port.CellsSet(cx, cRes, oldres)
	pcRestore(cx)
	port.CellsDrop(cs, start)
	return 0
}

func pcPrep(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, out *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells) int32 {
	// Before a string is shown: the font resident, and M = Tm x CTM current.
	pcEnsureFont(src, ar, dc, a, b, st, cx, out, f0, f1, f2, f3)
	pcUpdateM(cx)
	if port.CellsAt(cx, cSlot) < 0 {
		pcWarnSet(cx, wText)
	}
	return 0
}

func pcOp(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, ox *port.Cells, cs *port.Cells, out *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, gl *port.Cells, et *port.Cells, sp *port.Cells, op int32, n int32) int32 {
	// Execute one operator; `ox` holds its n operands. Unknown operators do
	// nothing (their operands are dropped by the caller).
	if op == opSave {
		pcSave(cx)
		return 0
	}
	if op == opRestore {
		pcRestore(cx)
		return 0
	}
	if op == opCm {
		if n >= 6 {
			fx.MxSet(cx, cTmp, pcNum(ox, n, 0), pcNum(ox, n, 1), pcNum(ox, n, 2), pcNum(ox, n, 3), pcNum(ox, n, 4), pcNum(ox, n, 5))
			fx.MxMul(cx, cCur+gCtm, cTmp, cCur+gCtm)
		}
		return 0
	}
	if op == opBt {
		fx.MxIdent(cx, cTm)
		fx.MxIdent(cx, cTlm)
		port.CellsSet(cx, cIntext, 1)
		return 0
	}
	if op == opEt {
		port.CellsSet(cx, cIntext, 0)
		return 0
	}
	if op == opTf {
		pcTf(src, ar, dc, a, b, st, cx, ox, n)
		return 0
	}
	if op == opTchar {
		fx.FxPut(cx, cCur+gTc, pcNum(ox, n, 0))
		return 0
	}
	if op == opTword {
		fx.FxPut(cx, cCur+gTw, pcNum(ox, n, 0))
		return 0
	}
	if op == opTscale {
		fx.FxPut(cx, cCur+gTh, fx.FxMuldiv(pcNum(ox, n, 0), int64(1), int64(100)))
		return 0
	}
	if op == opTlead {
		fx.FxPut(cx, cCur+gTl, pcNum(ox, n, 0))
		return 0
	}
	if op == opTrise {
		fx.FxPut(cx, cCur+gRise, pcNum(ox, n, 0))
		return 0
	}
	if op == opTmode {
		port.CellsSet(cx, cCur+gMode, fx.FxRound(pcNum(ox, n, 0)))
		return 0
	}
	if op == opTd {
		pcTd(cx, pcNum(ox, n, 0), pcNum(ox, n, 1))
		return 0
	}
	if op == opTdl {
		fx.FxPut(cx, cCur+gTl, int64(0)-pcNum(ox, n, 1))
		pcTd(cx, pcNum(ox, n, 0), pcNum(ox, n, 1))
		return 0
	}
	if op == opTm {
		if n >= 6 {
			pcSetTm(cx, pcNum(ox, n, 0), pcNum(ox, n, 1), pcNum(ox, n, 2), pcNum(ox, n, 3), pcNum(ox, n, 4), pcNum(ox, n, 5))
		}
		return 0
	}
	if op == opTstar {
		pcNextLine(cx)
		return 0
	}
	if op == opShow {
		if (n >= 1) && (pcKind(ox, 0) == kStr) {
			pcPrep(src, ar, dc, a, b, st, cx, out, f0, f1, f2, f3)
			pcShowStr(cx, ox, gl, et, f0, f1, f2, f3, 0)
		}
		return 0
	}
	if op == opShowarr {
		if (n >= 1) && (pcKind(ox, 0) == kArr) {
			pcPrep(src, ar, dc, a, b, st, cx, out, f0, f1, f2, f3)
			pcShowArr(cx, ox, gl, et, f0, f1, f2, f3, 0)
		}
		return 0
	}
	if op == opQuote {
		if (n >= 1) && (pcKind(ox, 0) == kStr) {
			pcNextLine(cx)
			pcPrep(src, ar, dc, a, b, st, cx, out, f0, f1, f2, f3)
			pcShowStr(cx, ox, gl, et, f0, f1, f2, f3, 0)
		}
		return 0
	}
	if op == opDquote {
		if (n >= 3) && (pcKind(ox, 2) == kStr) {
			fx.FxPut(cx, cCur+gTw, pcNum(ox, n, 0))
			fx.FxPut(cx, cCur+gTc, pcNum(ox, n, 1))
			pcNextLine(cx)
			pcPrep(src, ar, dc, a, b, st, cx, out, f0, f1, f2, f3)
			pcShowStr(cx, ox, gl, et, f0, f1, f2, f3, 2)
		}
		return 0
	}
	if op == opDo {
		pcDo(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, sp, n)
		return 0
	}
	if op == opBdc {
		pcMcBegin(src, ar, dc, a, b, st, cx, ox, gl, et, sp, n, 1)
		return 0
	}
	if op == opBmc {
		pcMcBegin(src, ar, dc, a, b, st, cx, ox, gl, et, sp, n, 0)
		return 0
	}
	if op == opEmc {
		pcMcEnd(cx, sp, gl)
		return 0
	}
	if op == opBi {
		pcSkipInline(cx, cs)
		return 0
	}
	if (op == opGray) || ((op == opRgb) || ((op == opCmyk) || ((op == opSc) || (op == opScn)))) {
		pcSetColor(cx, ox, n)
		return 0
	}
	if op == opCs {
		port.CellsSet(cx, cCur+gColor, 0)
		if (n >= 1) && (pcKind(ox, 0) == kName) {
			port.CellsSet(cx, cCur+gFam, 0)
			if pcEntryNameIs(ox, 0, pdfnames.PnDeviceGray()) == 1 {
				port.CellsSet(cx, cCur+gFam, 1)
			}
			if pcEntryNameIs(ox, 0, pdfnames.PnDeviceRgb()) == 1 {
				port.CellsSet(cx, cCur+gFam, 2)
			}
			if pcEntryNameIs(ox, 0, pdfnames.PnDeviceCmyk()) == 1 {
				port.CellsSet(cx, cCur+gFam, 3)
			}
		}
		return 0
	}
	if op == opGs {
		if (n >= 1) && (pcKind(ox, 0) == kName) {
			var raw int32 = pcResEntry(src, ar, dc, a, b, st, cx, ox, pdfnames.PnExtGState(), 0)
			if raw != 0 {
				var gd int32 = pdfdoc.PdResolve(src, ar, dc, a, b, st, raw)
				if gd != 0 {
					var cav int32 = pdfdoc.PdDget(src, ar, dc, a, b, st, gd, pdfnames.PnCa())
					if cav != 0 {
						var al int32 = fx.FxRound(fx.FxMul(pcArFx64(ar, cav), fx.FxOfInt(1000)))
						if al < 0 {
							port.CellsSet(cx, cCur+gAlpha, 0)
						} else if al > 1000 {
							port.CellsSet(cx, cCur+gAlpha, 1000)
						} else {
							port.CellsSet(cx, cCur+gAlpha, al)
						}
					}
				}
			}
			if pdfsrc.PsMissed(src) {
				port.CellsSet(cx, cAbort, 1)
			}
		}
		return 0
	}
	return 0
}

func pcRun(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, ox *port.Cells, cs *port.Cells, out *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, gl *port.Cells, et *port.Cells, sp *port.Cells, start int32, end int32) int32 {
	// Run the content bytes cs[start, end): read operands, then execute each
	// operator. The caller's lexer position, graphics-state floor and marked-
	// content floor are kept and restored, so a form can run inside an operator.
	var oldpos int32 = port.CellsAt(cx, cPos)
	var oldend int32 = port.CellsAt(cx, cEnd)
	var oldgs int32 = port.CellsAt(cx, cGsbase)
	var oldmcb int32 = port.CellsAt(cx, cMcbase)
	var oldover int32 = port.CellsAt(cx, cMcover)
	var oldtop int32 = port.CellsAt(cx, cMctop)
	var r int32 = 1
	var opc int32 = 0
	var nop int32 = 0
	var ops int32 = 0
	port.CellsSet(cx, cPos, start)
	port.CellsSet(cx, cEnd, end)
	port.CellsSet(cx, cGsbase, port.CellsAt(cx, cDepth))
	port.CellsSet(cx, cMcbase, port.CellsAt(cx, cMcdepth))
	port.CellsSet(cx, cMcover, 0)
	pcOxClear(cx, ox)
	for (r != 0) && (port.CellsAt(cx, cAbort) == 0) {
		r = pcLex(cx, ox, cs)
		if r == 2 {
			ops = port.CellsAt(cx, cOps) + 1
			port.CellsSet(cx, cOps, ops)
			if ops > port.CellsAt(cx, cOplim) {
				port.LimitBreach(5, ops)
			}
			opc = port.CellsAt(cx, cOp)
			nop = port.CellsAt(cx, cOxn)
			pcOp(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, sp, opc, nop)
			pcOxClear(cx, ox)
		}
	}
	// What the stream left open: spans, graphics states.
	for port.CellsAt(cx, cMcdepth) > port.CellsAt(cx, cMcbase) {
		pcWarnSet(cx, wMc)
		pcMcPop(cx, sp, gl, 1)
	}
	for port.CellsAt(cx, cDepth) > port.CellsAt(cx, cGsbase) {
		port.CellsSet(cx, cDepth, port.CellsAt(cx, cDepth)-1)
	}
	port.CellsSet(cx, cMctop, oldtop)
	pcMcRecompute(cx, sp)
	port.CellsSet(cx, cMcover, oldover)
	port.CellsSet(cx, cMcbase, oldmcb)
	port.CellsSet(cx, cGsbase, oldgs)
	port.CellsSet(cx, cPos, oldpos)
	port.CellsSet(cx, cEnd, oldend)
	return 0
}

const wordGapPm int32 = 160

const wordBackPm int32 = 400

const offsetPm int32 = 450

const lineBackPm int32 = 600

const lineGapPm int32 = 2000

func pcAxis(rot int32) int32 {
	// The writing axis a rotation is within three degrees of, else -1 (a glyph run
	// at another angle is measured along its own direction, `pc-rot-gap`).
	var a int32 = ((rot + 4500) / 9000) % 4
	var d int32 = rot - (a * 9000)
	if d < 0 {
		d = 0 - d
	}
	if d > 18000 {
		d = 36000 - d
	}
	if d <= 300 {
		return a
	}
	return -1
}

func pcOffset(gl *port.Cells, j int32, axis int32) int32 {
	// Where glyph j's baseline is across its writing axis, in centipoints.
	if axis == 1 {
		return evidence.GlGet(gl, j, evidence.GfX1())
	}
	if axis == 3 {
		return evidence.GlGet(gl, j, evidence.GfX0())
	}
	return evidence.GlGet(gl, j, evidence.GfBaseline())
}

func pcGap(gl *port.Cells, p int32, g int32, axis int32) int32 {
	// The space along the axis between glyph p and the glyph g after it
	// (negative when they overlap or g is before p).
	if axis == 0 {
		return evidence.GlGet(gl, g, evidence.GfX0()) - evidence.GlGet(gl, p, evidence.GfX1())
	}
	if axis == 2 {
		return evidence.GlGet(gl, p, evidence.GfX0()) - evidence.GlGet(gl, g, evidence.GfX1())
	}
	if axis == 1 {
		return evidence.GlGet(gl, p, evidence.GfY0()) - evidence.GlGet(gl, g, evidence.GfY1())
	}
	return evidence.GlGet(gl, g, evidence.GfY0()) - evidence.GlGet(gl, p, evidence.GfY1())
}

func pcRotGap(gl *port.Cells, p int32, g int32, size int32) int32 {
	// For text at an arbitrary angle: the distance between glyph p's centre and
	// glyph g's, along the writing direction, less 60 percent of the size (the
	// two half-advances of adjacent letters), so it reads as `pc-gap` does.
	var rot int32 = evidence.GlGet(gl, p, evidence.GfRot())
	var ux int64 = fx.FxCos(rot)
	var uy int64 = int64(0) - fx.FxSin(rot)
	var dx2 int32 = (evidence.GlGet(gl, g, evidence.GfX0()) + evidence.GlGet(gl, g, evidence.GfX1())) - (evidence.GlGet(gl, p, evidence.GfX0()) + evidence.GlGet(gl, p, evidence.GfX1()))
	var dy2 int32 = (evidence.GlGet(gl, g, evidence.GfY0()) + evidence.GlGet(gl, g, evidence.GfY1())) - (evidence.GlGet(gl, p, evidence.GfY0()) + evidence.GlGet(gl, p, evidence.GfY1()))
	var al2 int64 = fx.FxMul(fx.FxOfInt(dx2), ux) + fx.FxMul(fx.FxOfInt(dy2), uy)
	return fx.FxRound(al2/int64(2)) - ((size * 600) / 1000)
}

func pcRotOff(gl *port.Cells, p int32, g int32) int32 {
	// The distance between the two glyphs' centres across the writing direction.
	var rot int32 = evidence.GlGet(gl, p, evidence.GfRot())
	var sn int64 = fx.FxSin(rot)
	var cs int64 = fx.FxCos(rot)
	var dx2 int32 = (evidence.GlGet(gl, g, evidence.GfX0()) + evidence.GlGet(gl, g, evidence.GfX1())) - (evidence.GlGet(gl, p, evidence.GfX0()) + evidence.GlGet(gl, p, evidence.GfX1()))
	var dy2 int32 = (evidence.GlGet(gl, g, evidence.GfY0()) + evidence.GlGet(gl, g, evidence.GfY1())) - (evidence.GlGet(gl, p, evidence.GfY0()) + evidence.GlGet(gl, p, evidence.GfY1()))
	var pe int32 = fx.FxRound((fx.FxMul(fx.FxOfInt(dx2), sn) + fx.FxMul(fx.FxOfInt(dy2), cs)) / int64(2))
	if pe < 0 {
		return 0 - pe
	}
	return pe
}

func pcPairGap(gl *port.Cells, p int32, g int32, axis int32, size int32) int32 {
	if axis < 0 {
		return pcRotGap(gl, p, g, size)
	}
	return pcGap(gl, p, g, axis)
}

func pcPairOff(gl *port.Cells, p int32, g int32, axis int32) int32 {
	// How far glyph g's baseline is from glyph p's, across the writing axis.
	if axis < 0 {
		return pcRotOff(gl, p, g)
	}
	var d int32 = pcOffset(gl, p, axis) - pcOffset(gl, g, axis)
	if d < 0 {
		return 0 - d
	}
	return d
}

func pcSpaceCp(cp int32) int32 {
	// 1 for a code point that separates words: the spaces (U+0020, U+00A0,
	// U+1680, U+2000..200A, U+202F, U+205F, U+3000) and the tab.
	if (cp == 32) || ((cp == 160) || ((cp == 9) || ((cp == 5760) || ((cp == 8239) || ((cp == 8287) || (cp == 12288)))))) {
		return 1
	}
	if (cp >= 8192) && (cp <= 8202) {
		return 1
	}
	return 0
}

func pcCl(v int32) int32 {
	// Clamp a distance to +-1,000,000 centipoints so a per-mille product fits an I32.
	if v > 1000000 {
		return 1000000
	}
	if v < -1000000 {
		return -1000000
	}
	return v
}

func pcRotSame(r1 int32, r2 int32) int32 {
	// 1 when two rotations (centi-degrees) agree to half a degree.
	var d int32 = r1 - r2
	if d < 0 {
		d = 0 - d
	}
	if d > 18000 {
		d = 36000 - d
	}
	if d <= 50 {
		return 1
	}
	return 0
}

func pcContinues(gl *port.Cells, p int32, g int32) int32 {
	// 1 when glyph g continues the word glyph p is in: the same rotation, on the
	// same baseline (to 45 percent of the size: sub- and superscripts stay), and
	// the gap along the axis neither a word space nor a step back.
	var rot int32 = evidence.GlGet(gl, p, evidence.GfRot())
	var axis int32 = pcAxis(rot)
	var size int32 = evidence.GlGet(gl, g, evidence.GfSize())
	var sizep int32 = evidence.GlGet(gl, p, evidence.GfSize())
	var sz int32 = size
	var gap int32 = 0
	var off int32 = 0
	if pcRotSame(rot, evidence.GlGet(gl, g, evidence.GfRot())) == 0 {
		return 0
	}
	if sizep > sz {
		sz = sizep
	}
	if sz > 200000 {
		sz = 200000
	}
	if sz < (0 - 200000) {
		sz = 0 - 200000
	}
	off = pcCl(pcPairOff(gl, p, g, axis))
	if (off * 1000) > (sz * offsetPm) {
		return 0
	}
	gap = pcCl(pcPairGap(gl, p, g, axis, sz))
	if (gap * 1000) > (sz * wordGapPm) {
		return 0
	}
	if (gap * 1000) < (0 - (sz * wordBackPm)) {
		return 0
	}
	return 1
}

func pcCls(cp int32) int32 {
	// A code point's strength for reordering right-to-left text: 1 strong right-to-left
	// (Hebrew, Arabic, Syriac, Thaana, N'Ko and their presentation forms), 2 a left-to-right
	// letter or a digit (Arabic-Indic digits are digits: they run left to right inside
	// right-to-left text), 0 neutral (punctuation, symbols, what has no value).
	if cp < 33 {
		return 0
	}
	if ((cp >= 48) && (cp <= 57)) || (((cp >= 1632) && (cp <= 1641)) || ((cp >= 1776) && (cp <= 1785))) {
		return 2
	}
	if ((cp >= 1424) && (cp <= 2303)) || (((cp >= 64285) && (cp <= 65023)) || ((cp >= 65136) && (cp <= 65279))) {
		return 1
	}
	if ((cp >= 65) && (cp <= 90)) || ((cp >= 97) && (cp <= 122)) {
		return 2
	}
	if (cp >= 192) && ((cp < 8192) && (cp != 215)) {
		return 2
	}
	if (cp >= 12352) && (cp < 65000) {
		return 2
	}
	return 0
}

func pcGcls(gl *port.Cells, j int32) int32 {
	return pcCls(evidence.GlGet(gl, j, evidence.GfCp()))
}

func pcGlyphOut(et *port.Cells, gl *port.Cells, j int32) int32 {
	// Append glyph j's text (every code point it stands for, or U+FFFD) to the evidence text.
	var ts int32 = evidence.GlGet(gl, j, evidence.GfTstart())
	var tl int32 = evidence.GlGet(gl, j, evidence.GfTlen())
	var cp int32 = evidence.GlGet(gl, j, evidence.GfCp())
	var k int32 = 0
	var cpv int32 = 0
	if (ts >= 0) && (tl > 0) {
		for k < tl {
			cpv = port.CellsAt(et, ts+k)
			evidence.EtxAppendCp(et, cpv)
			k += 1
		}
		return 0
	}
	if cp >= 0 {
		evidence.EtxAppendCp(et, cp)
	} else {
		evidence.EtxAppendCp(et, 65533)
	}
	return 0
}

func pcEmitWord(gl *port.Cells, et *port.Cells, wd *port.Cells, page int32, gfst int32, glst int32) int32 {
	// Record glyphs [gfst, glst] as a word: the union of their boxes, their text, the
	// dominant font and size of the first, and `hidden-text` as its source when every
	// glyph is render mode 3. A right-to-left word whose glyphs run left to right on the
	// page (visual order, as Skia and most producers write them) has its TEXT written in
	// logical order: the glyphs reversed, with the runs of digits and Latin letters in it
	// turned back. The glyphs themselves stay as they were shown.
	var x0 int32 = evidence.GlGet(gl, gfst, evidence.GfX0())
	var y0 int32 = evidence.GlGet(gl, gfst, evidence.GfY0())
	var x1 int32 = evidence.GlGet(gl, gfst, evidence.GfX1())
	var y1 int32 = evidence.GlGet(gl, gfst, evidence.GfY1())
	var j int32 = gfst
	var tstart int32 = -1
	var visible int32 = 0
	var nr int32 = 0
	var nl int32 = 0
	var cl int32 = 0
	var rtlw int32 = 0
	var kk int32 = 0
	var m int32 = 0
	for j <= glst {
		if evidence.GlGet(gl, j, evidence.GfX0()) < x0 {
			x0 = evidence.GlGet(gl, j, evidence.GfX0())
		}
		if evidence.GlGet(gl, j, evidence.GfY0()) < y0 {
			y0 = evidence.GlGet(gl, j, evidence.GfY0())
		}
		if evidence.GlGet(gl, j, evidence.GfX1()) > x1 {
			x1 = evidence.GlGet(gl, j, evidence.GfX1())
		}
		if evidence.GlGet(gl, j, evidence.GfY1()) > y1 {
			y1 = evidence.GlGet(gl, j, evidence.GfY1())
		}
		if evidence.GlGet(gl, j, evidence.GfMode()) != 3 {
			visible = 1
		}
		cl = pcGcls(gl, j)
		if cl == 1 {
			nr += 1
		}
		if cl == 2 {
			nl += 1
		}
		j += 1
	}
	if (nr > nl) && (glst > gfst) {
		if pcAxis(evidence.GlGet(gl, gfst, evidence.GfRot())) == 0 {
			if evidence.GlGet(gl, glst, evidence.GfX0()) >= evidence.GlGet(gl, gfst, evidence.GfX0()) {
				rtlw = 1
			}
		}
	}
	tstart = port.CellsLen(et)
	if rtlw == 0 {
		j = gfst
		for j <= glst {
			pcGlyphOut(et, gl, j)
			j += 1
		}
	} else {
		j = glst
		for j >= gfst {
			if pcGcls(gl, j) == 2 {
				kk = j
				for (kk > gfst) && (pcGcls(gl, kk-1) == 2) {
					kk -= 1
				}
				m = kk
				for m <= j {
					pcGlyphOut(et, gl, m)
					m += 1
				}
				j = kk - 1
			} else {
				pcGlyphOut(et, gl, j)
				j -= 1
			}
		}
	}
	var w int32 = evidence.WdNew(wd, page, x0, y0, x1, y1, gfst, (glst-gfst)+1)
	evidence.WdSet(wd, w, evidence.WfTstart(), tstart)
	evidence.WdSet(wd, w, evidence.WfTlen(), port.CellsLen(et)-tstart)
	evidence.WdSet(wd, w, evidence.WfFont(), evidence.GlGet(gl, gfst, evidence.GfFont()))
	evidence.WdSet(wd, w, evidence.WfSize(), evidence.GlGet(gl, gfst, evidence.GfSize()))
	if visible == 0 {
		evidence.WdSet(wd, w, evidence.WfSrc(), model.SrHiddenText())
	}
	j = gfst
	for j <= glst {
		evidence.GlSet(gl, j, evidence.GfWord(), w)
		j += 1
	}
	return w
}

func pcSwapRows(wd *port.Cells, i int32, j int32) int32 {
	var k int32 = 0
	var u int32 = 0
	var v int32 = 0
	for k < 16 {
		u = port.CellsAt(wd, (i*16)+k)
		v = port.CellsAt(wd, (j*16)+k)
		port.CellsSet(wd, (i*16)+k, v)
		port.CellsSet(wd, (j*16)+k, u)
		k += 1
	}
	return 0
}

func pcRevRows(wd *port.Cells, a int32, b int32) int32 {
	var i int32 = a
	var j int32 = b
	for i < j {
		pcSwapRows(wd, i, j)
		i += 1
		j -= 1
	}
	return 0
}

func pcWcls(gl *port.Cells, wd *port.Cells, w int32) int32 {
	// 2 when the word has more left-to-right letters and digits than right-to-left letters.
	var g0 int32 = evidence.WdGet(wd, w, evidence.WfGfirst())
	var gn int32 = evidence.WdGet(wd, w, evidence.WfGcount())
	var j int32 = 0
	var nr int32 = 0
	var nl int32 = 0
	var cl int32 = 0
	for j < gn {
		cl = pcGcls(gl, g0+j)
		if cl == 1 {
			nr += 1
		}
		if cl == 2 {
			nl += 1
		}
		j += 1
	}
	if nr > nl {
		return 1
	}
	return 2
}

func pcLineBidi(gl *port.Cells, wd *port.Cells, ln *port.Cells, lidx int32, wfst int32, wlst int32) int32 {
	// Line lidx holds words [wfst, wlst]. When more of its glyphs are right-to-left than
	// left-to-right it is a right-to-left line (`ld-rtl`); if the words run left to right on
	// the page, their ORDER is made logical: reversed, with runs of left-to-right words
	// turned back; each word's glyphs are re-pointed at it and its gap is the space to
	// the word that follows it in that order.
	var w int32 = wfst
	var nr int32 = 0
	var nl int32 = 0
	var j int32 = 0
	var cl int32 = 0
	var a int32 = 0
	var z int32 = 0
	var g0 int32 = 0
	var gn int32 = 0
	for w <= wlst {
		g0 = evidence.WdGet(wd, w, evidence.WfGfirst())
		gn = evidence.WdGet(wd, w, evidence.WfGcount())
		j = 0
		for j < gn {
			cl = pcGcls(gl, g0+j)
			if cl == 1 {
				nr += 1
			}
			if cl == 2 {
				nl += 1
			}
			j += 1
		}
		w += 1
	}
	if nr <= nl {
		return 0
	}
	evidence.LnSet(ln, lidx, evidence.LfDir(), evidence.LdRtl())
	if pcAxis(evidence.GlGet(gl, evidence.WdGet(wd, wfst, evidence.WfGfirst()), evidence.GfRot())) != 0 {
		return 0
	}
	if evidence.WdGet(wd, wlst, evidence.WfX0()) < evidence.WdGet(wd, wfst, evidence.WfX0()) {
		return 0
	}
	if wfst == wlst {
		return 0
	}
	pcRevRows(wd, wfst, wlst)
	a = wfst
	for a <= wlst {
		if pcWcls(gl, wd, a) == 2 {
			z = a
			for (z < wlst) && (pcWcls(gl, wd, z+1) == 2) {
				z += 1
			}
			pcRevRows(wd, a, z)
			a = z + 1
		} else {
			a += 1
		}
	}
	w = wfst
	for w <= wlst {
		g0 = evidence.WdGet(wd, w, evidence.WfGfirst())
		gn = evidence.WdGet(wd, w, evidence.WfGcount())
		j = 0
		for j < gn {
			evidence.GlSet(gl, g0+j, evidence.GfWord(), w)
			j += 1
		}
		z = -1
		if w < wlst {
			z = evidence.WdGet(wd, w, evidence.WfX0()) - evidence.WdGet(wd, w+1, evidence.WfX1())
		}
		evidence.WdSet(wd, w, evidence.WfGap(), z)
		w += 1
	}
	return 0
}

func PcGroup(gl *port.Cells, et *port.Cells, wd *port.Cells, ln *port.Cells, page int32, g0 int32, w0 int32) int32 {
	// Group the glyphs from g0 on into words, and the words from w0 on into lines.
	var g1 int32 = evidence.GlCount(gl)
	var i int32 = g0
	var cur int32 = -1
	for i < g1 {
		if pcSpaceCp(evidence.GlGet(gl, i, evidence.GfCp())) == 1 {
			if cur >= 0 {
				pcEmitWord(gl, et, wd, page, cur, i-1)
				cur = -1
			}
		} else {
			if cur >= 0 {
				if pcContinues(gl, i-1, i) == 0 {
					pcEmitWord(gl, et, wd, page, cur, i-1)
					cur = -1
				}
			}
			if cur < 0 {
				cur = i
			}
		}
		i += 1
	}
	if cur >= 0 {
		pcEmitWord(gl, et, wd, page, cur, g1-1)
		cur = -1
	}
	// Lines: consecutive words on one baseline, in order.
	var nw int32 = evidence.WdCount(wd)
	var j int32 = w0
	var lfirst int32 = -1
	var prev int32 = -1
	var lnx int32 = 0
	var x0 int32 = 0
	var y0 int32 = 0
	var x1 int32 = 0
	var y1 int32 = 0
	var gf0 int32 = 0
	var gfp int32 = 0
	var glast int32 = 0
	var axis int32 = 0
	var joins int32 = 0
	var gap int32 = 0
	var sz int32 = 0
	var off int32 = 0
	for j <= nw {
		joins = 0
		if (j < nw) && (prev >= 0) {
			gf0 = evidence.WdGet(wd, j, evidence.WfGfirst())
			gfp = evidence.WdGet(wd, prev, evidence.WfGfirst())
			axis = pcAxis(evidence.GlGet(gl, gfp, evidence.GfRot()))
			if pcRotSame(evidence.GlGet(gl, gfp, evidence.GfRot()), evidence.GlGet(gl, gf0, evidence.GfRot())) == 1 {
				sz = evidence.GlGet(gl, gf0, evidence.GfSize())
				if evidence.GlGet(gl, gfp, evidence.GfSize()) > sz {
					sz = evidence.GlGet(gl, gfp, evidence.GfSize())
				}
				if sz > 200000 {
					sz = 200000
				}
				if sz < (0 - 200000) {
					sz = 0 - 200000
				}
				glast = (evidence.WdGet(wd, prev, evidence.WfGfirst()) + evidence.WdGet(wd, prev, evidence.WfGcount())) - 1
				off = pcCl(pcPairOff(gl, glast, gf0, axis))
				// The gap is between the previous word's LAST glyph and this word's first.
				gap = pcCl(pcPairGap(gl, glast, gf0, axis, sz))
				if (off * 1000) <= (sz * offsetPm) {
					if (gap * 1000) >= (0 - (sz * lineBackPm)) {
						if (gap * 1000) <= (sz * lineGapPm) {
							joins = 1
						}
					}
				}
			}
		}
		if joins == 1 {
			evidence.WdSet(wd, prev, evidence.WfGap(), gap)
			prev = j
		} else {
			// The line so far ends at `prev`: record it, then start a new one at j.
			if lfirst >= 0 {
				x0 = evidence.WdGet(wd, lfirst, evidence.WfX0())
				y0 = evidence.WdGet(wd, lfirst, evidence.WfY0())
				x1 = evidence.WdGet(wd, lfirst, evidence.WfX1())
				y1 = evidence.WdGet(wd, lfirst, evidence.WfY1())
				lnx = lfirst
				for lnx <= prev {
					if evidence.WdGet(wd, lnx, evidence.WfX0()) < x0 {
						x0 = evidence.WdGet(wd, lnx, evidence.WfX0())
					}
					if evidence.WdGet(wd, lnx, evidence.WfY0()) < y0 {
						y0 = evidence.WdGet(wd, lnx, evidence.WfY0())
					}
					if evidence.WdGet(wd, lnx, evidence.WfX1()) > x1 {
						x1 = evidence.WdGet(wd, lnx, evidence.WfX1())
					}
					if evidence.WdGet(wd, lnx, evidence.WfY1()) > y1 {
						y1 = evidence.WdGet(wd, lnx, evidence.WfY1())
					}
					lnx += 1
				}
				gfp = evidence.WdGet(wd, lfirst, evidence.WfGfirst())
				axis = pcAxis(evidence.GlGet(gl, gfp, evidence.GfRot()))
				lnx = evidence.LnNew(ln, page, x0, y0, x1, y1, lfirst, (prev-lfirst)+1, pcOffset(gl, gfp, axis))
				evidence.LnSet(ln, lnx, evidence.LfRot(), evidence.GlGet(gl, gfp, evidence.GfRot()))
				pcLineBidi(gl, wd, ln, lnx, lfirst, prev)
				gfp = lfirst
				for gfp <= prev {
					evidence.WdSet(wd, gfp, evidence.WfLine(), lnx)
					gfp += 1
				}
			}
			lfirst = j
			prev = j
		}
		j += 1
	}
	return 0
}

func pcBeginPage(cx *port.Cells, page int32) int32 {
	// Reset everything a page owns; the fonts (the document's) stay.
	port.CellsSet(cx, cPage, page)
	port.CellsSet(cx, cWarn, 0)
	port.CellsSet(cx, cOps, 0)
	port.CellsSet(cx, cAbort, 0)
	port.CellsSet(cx, cPos, 0)
	port.CellsSet(cx, cEnd, 0)
	port.CellsSet(cx, cOxn, 0)
	port.CellsSet(cx, cCdepth, 0)
	port.CellsSet(cx, cOp, 0)
	port.CellsSet(cx, cRes, 0)
	port.CellsSet(cx, cSlot, -1)
	port.CellsSet(cx, cDepth, 0)
	port.CellsSet(cx, cFdepth, 0)
	port.CellsSet(cx, cStm, 0)
	port.CellsSet(cx, cMctop, -1)
	port.CellsSet(cx, cMcdepth, 0)
	port.CellsSet(cx, cMcbase, 0)
	port.CellsSet(cx, cMcover, 0)
	port.CellsSet(cx, cCurmcid, -1)
	port.CellsSet(cx, cCurart, 0)
	port.CellsSet(cx, cIntext, 0)
	port.CellsSet(cx, cGsbase, 0)
	fx.MxIdent(cx, cTm)
	fx.MxIdent(cx, cTlm)
	fx.MxIdent(cx, cM)
	return 0
}

func PcPage(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, ox *port.Cells, cs *port.Cells, out *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, gl *port.Cells, et *port.Cells, sp *port.Cells, pg *port.Cells, pi int32, page int32, wd *port.Cells, ln *port.Cells) int32 {
	// Interpret page index pi of the page table pg (page number `page`, 1-based, is
	// what the evidence records): its content streams, then the words and lines.
	// Answers 0, or 7 (`need-bytes`) when the source missed: then nothing written is
	// to be used and the caller re-runs on a fresh view (D075).
	var con int32 = pdfdoc.PdPgContents(pg, pi)
	var g0 int32 = evidence.GlCount(gl)
	var w0 int32 = evidence.WdCount(wd)
	var el int32 = 0
	var eh int32 = 0
	var endcs int32 = 0
	pcBeginPage(cx, page)
	pcBaseMatrix(cx, pdfdoc.PdPgCrop(pg, pi, 0), pdfdoc.PdPgCrop(pg, pi, 1), pdfdoc.PdPgCrop(pg, pi, 2), pdfdoc.PdPgCrop(pg, pi, 3), pdfdoc.PdPgRotate(pg, pi))
	pcGsReset(cx)
	port.CellsSet(cx, cRes, pdfdoc.PdPgResources(pg, pi))
	port.CellsDrop(cs, 0)
	if con != 0 {
		if pdflex.PlKindOf(ar, con) == 8 {
			pcAppendStream(src, ar, dc, a, b, st, cx, out, cs, con)
		}
		if pdflex.PlKindOf(ar, con) == 6 {
			el = pdflex.PlFirst(ar, con)
			for (el != 0) && (port.CellsAt(cx, cAbort) == 0) {
				eh = pdfdoc.PdResolve(src, ar, dc, a, b, st, el)
				if pdfsrc.PsMissed(src) {
					port.CellsSet(cx, cAbort, 1)
				}
				if (eh != 0) && (pdflex.PlKindOf(ar, eh) == 8) {
					pcAppendStream(src, ar, dc, a, b, st, cx, out, cs, eh)
				}
				el = pdflex.PlNext(ar, el)
			}
		}
	}
	if port.CellsAt(cx, cAbort) == 1 {
		return 7
	}
	endcs = port.CellsLen(cs)
	pcRun(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, sp, 0, endcs)
	if port.CellsAt(cx, cAbort) == 1 {
		return 7
	}
	if pdfsrc.PsMissed(src) {
		return 7
	}
	PcGroup(gl, et, wd, ln, page, g0, w0)
	return 0
}

func PcDocument(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, ox *port.Cells, cs *port.Cells, out *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, gl *port.Cells, et *port.Cells, sp *port.Cells, pg *port.Cells, wd *port.Cells, ln *port.Cells) int32 {
	// Every page of an opened document (`pd-open` has answered 0): clears `cx`,
	// then `pc-page` for each page. Answers 0, or 7 when the source missed.
	PcInit(cx, ox)
	var n int32 = pdfdoc.PdPages(src, ar, dc, a, b, st, pg)
	var i int32 = 0
	var status int32 = 0
	if n < 0 {
		return 7
	}
	for i < n {
		status = PcPage(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, sp, pg, i, i+1, wd, ln)
		if status == 7 {
			return 7
		}
		i += 1
	}
	return 0
}
